import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Segment","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/segment.md","filePath":"documentation/segment.md","lastUpdated":1788551488000}`),a={name:`documentation/segment.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="segment" tabindex="-1">Segment <a class="header-anchor" href="#segment" aria-label="Permalink to “Segment”">​</a></h1><p>A <strong>Segment</strong> is a reusable collection of form fields within a site configuration. Its structure is identical to a standard site form, but it does <strong>not</strong> run automatically on page load. Instead, a segment is executed on demand by its <strong>unique name</strong> through automated triggers or field response actions.</p><img src="/image/segment-list.png" alt="Segment List Interface" style="max-width:400px;border-radius:8px;margin:16px 0;"><p>You can access segments by opening your site configuration and switching to the <strong>Segments</strong> tab next to <strong>Site Pages</strong>. Click the blue <strong><code>+</code></strong> button to create a new segment. The table displays:</p><ul><li><strong>S.NO</strong>: The serial index and drag-handle to reorder segments.</li><li><strong>ACTIVE</strong>: An instant toggle switch to activate or deactivate the segment.</li><li><strong>SEGMENT NAME</strong>: The unique identifier used to call and execute the segment.</li></ul><hr><h2 id="segment-actions" tabindex="-1">Segment Actions <a class="header-anchor" href="#segment-actions" aria-label="Permalink to “Segment Actions”">​</a></h2><p>Each segment row provides management controls and a dedicated actions menu for quick workflow operations.</p><img src="/image/segment-actions.png" alt="Segment Actions Menu" style="max-width:460px;border-radius:8px;margin:16px 0;"><table tabindex="0"><thead><tr><th>Action</th><th>Control</th><th>Description</th></tr></thead><tbody><tr><td><strong>Field Count / Manage Fields</strong></td><td>Blue Button <code>(n)</code></td><td>Displays the number of fields configured in the segment. Click to open and manage its field list.</td></tr><tr><td><strong>Edit Segment</strong></td><td>Orange <code>Edit</code> Button</td><td>Opens the Segment Settings modal to update its name, description, and tab targeting options.</td></tr><tr><td><strong>Duplicate Segment</strong></td><td>Menu Option</td><td>Clones the segment along with all its configured fields into a new copy.</td></tr><tr><td><strong>Copy Segment</strong></td><td>Menu Option</td><td>Copies the complete segment configuration data to your clipboard.</td></tr><tr><td><strong>Paste Segment</strong></td><td>Menu Option</td><td>Pastes a previously copied segment into the active site.</td></tr><tr><td><strong>Delete Segment</strong></td><td>Menu Option (Red)</td><td>Permanently deletes the segment and its fields.</td></tr></tbody></table><hr><h2 id="segment-settings-tab-options" tabindex="-1">Segment Settings &amp; Tab Options <a class="header-anchor" href="#segment-settings-tab-options" aria-label="Permalink to “Segment Settings &amp; Tab Options”">​</a></h2><p>Clicking the <strong>Edit</strong> button on any segment opens the configuration modal.</p><h3 id="configuration-fields" tabindex="-1">Configuration Fields <a class="header-anchor" href="#configuration-fields" aria-label="Permalink to “Configuration Fields”">​</a></h3><ul><li><strong>Segment Name *</strong>: The unique name used to reference and run this segment (e.g., <code>run</code>, <code>all-done</code>).</li><li><strong>Segment Description</strong>: An optional descriptive note explaining the segment&#39;s purpose.</li><li><strong>Active/Inactive</strong>: Enable or disable execution for this segment.</li></ul><h3 id="view-field-element-in-tab" tabindex="-1">View Field Element in Tab <a class="header-anchor" href="#view-field-element-in-tab" aria-label="Permalink to “View Field Element in Tab”">​</a></h3><p>Because segments are independent workflows and are not tied to a single form page URL, the extension does not know by default which browser tab to target when you are building segment fields.</p><p>When <strong>View Field Element in Tab</strong> is toggled <strong>ON</strong>, two additional configuration options appear:</p><ul><li><strong>Target Page URL</strong>: Enter the full URL or path pattern of the page where the segment operates.</li><li><strong>Match Target URL Types</strong>: Choose how the target page URL is matched: <ul><li><strong>Match with Full URL</strong></li><li><strong>Match with URL pathname</strong></li><li><strong>Match with URL hostname</strong></li><li><strong>Match with RegEx</strong></li></ul></li></ul><h4 id="testing-field-selectors-with-tab-targeting" tabindex="-1">Testing Field Selectors with Tab Targeting <a class="header-anchor" href="#testing-field-selectors-with-tab-targeting" aria-label="Permalink to “Testing Field Selectors with Tab Targeting”">​</a></h4><p>Once <strong>View Field Element in Tab</strong> is configured with your target page, you can test and inspect field selectors directly:</p><img src="/image/segment-selector-search.png" alt="Field Selector Search" style="max-width:520px;border-radius:8px;margin:16px 0;"><p>When editing any field inside the segment, click the magnifying glass (<strong>Search</strong>) icon next to the selector input (e.g., <code>input#one</code>). The extension will locate, verify, and highlight the matching element on the corresponding open browser tab in real time.</p><hr><h2 id="predefined-segments" tabindex="-1">Predefined Segments <a class="header-anchor" href="#predefined-segments" aria-label="Permalink to “Predefined Segments”">​</a></h2><p>The extension includes built-in reserved segments designed for specific status bar workflows:</p><table tabindex="0"><thead><tr><th>Segment Name</th><th>Description</th></tr></thead><tbody><tr><td><code>{MARK AS SAVED}</code></td><td>Executed automatically when you click the <strong>Mark as Saved</strong> button on the extension <a href="/documentation/settings.html#status-bar">Status Bar</a>.</td></tr></tbody></table><hr><h2 id="how-to-execute-a-segment" tabindex="-1">How to Execute a Segment <a class="header-anchor" href="#how-to-execute-a-segment" aria-label="Permalink to “How to Execute a Segment”">​</a></h2><p>Segments do not execute automatically on page load. You can trigger segment execution in the following ways:</p><ol><li><strong><a href="/documentation/form-fields/field-response-action.html">Field Response Action</a></strong>: Trigger a segment immediately upon a field&#39;s success or error condition.</li><li><strong><a href="/documentation/field-types/execute-segment.html">Execute Segment Field Type</a></strong>: Add an <code>Execute Segment</code> step inside any standard form workflow, optionally passing custom JSON environment variables.</li><li><strong><a href="/documentation/field-types/loop.html">Loop Field Type</a></strong>: Execute a segment repeatedly for each iteration of a table row or list item.</li><li><strong>Status Bar Trigger</strong>: Run <code>{MARK AS SAVED}</code> on demand using the floating status bar.</li></ol>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};